import { z } from "zod";
import { isValidTimezone } from "../../utils/timezone";

const groupNameSchema = z
  .string()
  .trim()
  .min(1, "Group name is required")
  .max(100, "Group name must be at most 100 characters");

const groupDescriptionSchema = z
  .string()
  .trim()
  .max(500, "Group description must be at most 500 characters");

// Shareable join codes are always JOIN_CODE_LENGTH characters long and
// generated by group.service.ts. The constant lives here (the leaf module
// the service already imports from) so code generation and join-code
// validation can never drift apart.
export const JOIN_CODE_LENGTH = 8;

export const createGroupSchema = z.strictObject({
  name: groupNameSchema,
  description: groupDescriptionSchema.nullable().optional(),
});

export const updateGroupSchema = z
  .strictObject({
    name: groupNameSchema.optional(),
    description: groupDescriptionSchema.nullable().optional(),
    // IANA name used for chore deadlines; affects future slots only.
    timezone: z
      .string()
      .trim()
      .refine(isValidTimezone, "Unknown timezone")
      .optional(),
  })
  .refine((data) => Object.keys(data).length > 0, {
    message: "At least one of name, description or timezone is required",
  });

// Prisma ids are cuids: "c" followed by 20+ base36 characters.
// Exported for reuse by the group-member module's param schemas.
export const cuidPattern = /^c[0-9a-z]{20,}$/;

export const groupIdParamSchema = z.object({
  groupId: z
    .string()
    .trim()
    .regex(cuidPattern, "Group id must be a valid id"),
});

// Lifecycle filter for GET /api/groups. Defaults to "active", so archived
// groups are never returned implicitly; unknown params/values are rejected
// (strictObject) following the body-validation convention.
export const listGroupsQuerySchema = z.strictObject({
  status: z
    .enum(["active", "archived", "all"])
    .default("active"),
});

// Body of POST /api/groups/join. Codes are stored uppercase, so the input
// is trimmed and upper-cased before the exact-length check; a well-formed
// but unknown code is still rejected downstream by the service (404).
export const joinGroupSchema = z.strictObject({
  joinCode: z
    .string()
    .trim()
    .toUpperCase()
    .length(
      JOIN_CODE_LENGTH,
      `Join code must be ${JOIN_CODE_LENGTH} characters`,
    ),
});

export type CreateGroupInput = z.infer<typeof createGroupSchema>;
export type JoinGroupInput = z.infer<typeof joinGroupSchema>;
export type UpdateGroupInput = z.infer<typeof updateGroupSchema>;
export type GroupIdParam = z.infer<typeof groupIdParamSchema>;
export type ListGroupsQuery = z.infer<typeof listGroupsQuerySchema>;
